-- Nexmark q14 on flink, BLACKHOLE sink variant. Calculation. Expression
-- filter plus a CASE projection - the query that is almost all scalar
-- expression evaluation.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q14bh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q14 (`auction` BIGINT, `bidder` BIGINT, `price` DOUBLE, `bidtimetype` STRING) WITH ('connector' = 'blackhole');
INSERT INTO sink_q14
SELECT auction, bidder, 0.908 * price AS price, CASE WHEN MOD(`datetime`, 2) = 0 THEN 'even' ELSE 'odd' END AS bidtimetype FROM bid WHERE 0.908 * price > 250;
